"""Parsing grades from text."""
from grades import Grade


def _parse_line(line):
    student, score = line.split(",")
    return Grade(student.strip(), int(score))


def parse_grades(text):
    """Parse lines of 'student,score' into Grade records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def largest_score(grades):
    """Return the largest score, or None when there are no grades."""
    values = [x.score for x in grades]
    return max(values) if values else None

